-- ============================================================
-- pg-xerp data-layer port: frmDeptSale2   (posts)
-- Dialect = pg's OWN proven fast-grid (sp_brand_grid2 = 88ms/100k)
-- + xErp's sp_<formid>_<verb> naming so crud.js resolves them.
-- Table created here; procs match the form's grafted form.json.
-- ============================================================
CREATE TABLE IF NOT EXISTS public."tblfrmDeptSale2" (
    "Id"        bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "sDate" text NOT NULL DEFAULT '',
    "eDate" text NOT NULL DEFAULT '',
    "InvNo" text NOT NULL DEFAULT '',
    "To_" text NOT NULL DEFAULT '',
    "WorkOrderNo_" text NOT NULL DEFAULT '',
    "FCODE"     text NOT NULL DEFAULT '',
    "User_Id"   text NOT NULL DEFAULT '',
    "Lock"      smallint NOT NULL DEFAULT 0,
    "LOCK_User_Id" text NOT NULL DEFAULT '',
    "Created_At" timestamptz NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION public.sp_frmDeptSale2_Grid2(
    p_pagesize integer, p_pageno integer, p_search text,
    p_formid text, p_fcode text, p_auth text)
RETURNS TABLE("Id" bigint, "Detail" text, "rc" bigint)
LANGUAGE plpgsql AS $function$
BEGIN
    RETURN QUERY
    SELECT t."Id", t.det, count(*) OVER() AS rc
    FROM (
        SELECT r."Id",
               json_build_object('sDate', r."sDate", 'eDate', r."eDate", 'InvNo', r."InvNo", 'To_', r."To_", 'WorkOrderNo_', r."WorkOrderNo_")::text AS det
        FROM public."tblfrmDeptSale2" r
        WHERE (p_search = '' OR r."sDate" ILIKE '%' || p_search || '%' OR r."eDate" ILIKE '%' || p_search || '%' OR r."InvNo" ILIKE '%' || p_search || '%' OR r."To_" ILIKE '%' || p_search || '%' OR r."WorkOrderNo_" ILIKE '%' || p_search || '%')
        ORDER BY r."Id" DESC
        LIMIT p_pagesize OFFSET (p_pageno - 1) * p_pagesize
    ) t;
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmDeptSale2_GridCount1(
    p_search text, p_formid text, p_fcode text, p_auth text)
RETURNS TABLE("rc" bigint) LANGUAGE plpgsql AS $function$
BEGIN
    RETURN QUERY SELECT count(*)::bigint FROM public."tblfrmDeptSale2";
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmDeptSale2_DFE1(
    p_id bigint, p_formid text, p_auth text, p_fcode text)
RETURNS TABLE("Id" bigint, "Detail" text)
LANGUAGE plpgsql AS $function$
BEGIN
    RETURN QUERY
    SELECT r."Id", json_build_object('sDate', r."sDate", 'eDate', r."eDate", 'InvNo', r."InvNo", 'To_', r."To_", 'WorkOrderNo_', r."WorkOrderNo_")::text
    FROM public."tblfrmDeptSale2" r
    WHERE r."Id" = p_id;
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmDeptSale2_SAVE(
    p_sdate text, p_edate text, p_invno text, p_to text, p_workorderno text, p_formid text, p_fcode text, p_auth text)
RETURNS TABLE("status" text, "message" text, "id" bigint)
LANGUAGE plpgsql AS $function$
DECLARE v_id bigint;
BEGIN
    INSERT INTO public."tblfrmDeptSale2" ("sDate", "eDate", "InvNo", "To_", "WorkOrderNo_")
    VALUES (p_sdate, p_edate, p_invno, p_to, p_workorderno)
    RETURNING "Id" INTO v_id;
    RETURN QUERY SELECT 'Success'::text, ''::text, v_id;
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmDeptSale2_UPDATE(
    p_id bigint, p_sdate text, p_edate text, p_invno text, p_to text, p_workorderno text, p_formid text, p_fcode text, p_auth text)
RETURNS TABLE("status" text, "message" text)
LANGUAGE plpgsql AS $function$
BEGIN
    IF EXISTS (SELECT 1 FROM public."tblfrmDeptSale2" WHERE "Id" = p_id AND "Lock" = 1) THEN
        RETURN QUERY SELECT 'Error'::text, 'RECORD IS LOCKED !!!'::text;
        RETURN;
    END IF;
    UPDATE public."tblfrmDeptSale2" SET "sDate" = p_sdate, "eDate" = p_edate, "InvNo" = p_invno, "To_" = p_to, "WorkOrderNo_" = p_workorderno WHERE "Id" = p_id;
    RETURN QUERY SELECT 'Success'::text, ''::text;
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmDeptSale2_Delete1(
    p_id bigint, p_formid text, p_auth text)
RETURNS TABLE("status" text, "message" text)
LANGUAGE plpgsql AS $function$
BEGIN
    IF EXISTS (SELECT 1 FROM public."tblfrmDeptSale2" WHERE "Id" = p_id AND "Lock" = 1) THEN
        RETURN QUERY SELECT 'Error'::text, 'RECORD IS LOCKED !!!'::text;
        RETURN;
    END IF;
    DELETE FROM public."tblfrmDeptSale2" WHERE "Id" = p_id;
    RETURN QUERY SELECT 'Success'::text, ''::text;
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmDeptSale2_LockUnlock1(
    p_formid text, p_auth text, p_company text, p_id bigint)
RETURNS TABLE("status" text, "message" text) LANGUAGE plpgsql AS $function$
BEGIN
    UPDATE public."tblfrmDeptSale2" SET "Lock" = CASE WHEN "Lock" = 0 THEN 1 ELSE 0 END
    WHERE "Id" = p_id;
    RETURN QUERY SELECT 'Success'::text, ''::text;
END $function$;
